import { useMemo, useSyncExternalStore } from "react"
import { createStore, entries, get, set, setMany, type UseStore } from "idb-keyval"

type Status = "loading" | "ready" | "error"

interface Snapshot<T> {
  items: T[]
  status: Status
  error?: Error
}

export interface Collection<T extends { id: string }> extends Snapshot<T> {
  add(item: T): Promise<void>
  update(id: string, patch: Partial<T>): Promise<void>
  remove(id: string): Promise<void>
  replaceAll(items: T[]): Promise<void>
}

interface Entry {
  snapshot: Snapshot<{ id: string }>
  listeners: Set<() => void>
  loaded: Promise<void>
}

const entriesByName = new Map<string, Entry>()
// keyed by name, not entry, so an import can order itself against collections nobody has opened yet
const queues = new Map<string, Promise<unknown>>()
let idbStore: UseStore | undefined

function db(): UseStore {
  idbStore ??= createStore("mini-app", "collections")
  return idbStore
}

function toError(cause: unknown): Error {
  return cause instanceof Error ? cause : new Error(String(cause))
}

function publish(entry: Entry, snapshot: Snapshot<{ id: string }>) {
  entry.snapshot = snapshot
  entry.listeners.forEach((listener) => listener())
}

function queueTail(name: string): Promise<unknown> {
  return queues.get(name) ?? Promise.resolve()
}

function getEntry(name: string, seed?: { id: string }[]): Entry {
  const existing = entriesByName.get(name)
  if (existing) return existing

  const entry: Entry = {
    snapshot: { items: [], status: "loading" },
    listeners: new Set(),
    loaded: Promise.resolve(),
  }
  entriesByName.set(name, entry)

  const pending = queueTail(name)
  entry.loaded = (async () => {
    try {
      await pending
      const stored = await get<{ id: string }[]>(name, db())
      if (stored !== undefined) {
        publish(entry, { items: stored, status: "ready" })
        return
      }
      const initial = seed ?? []
      if (seed) await set(name, initial, db())
      publish(entry, { items: initial, status: "ready" })
    } catch (cause) {
      publish(entry, { items: [], status: "error", error: toError(cause) })
    }
  })()

  return entry
}

/** Serializes writes per collection, imports included, so concurrent calls never drop each other's changes. */
function mutate<T extends { id: string }>(
  name: string,
  entry: Entry,
  change: (items: T[]) => T[] | null
): Promise<void> {
  const run = queueTail(name).then(async () => {
    await entry.loaded
    const { items, status, error } = entry.snapshot
    if (status === "error") throw error
    const next = change(items as T[])
    if (next === null) return
    await set(name, next, db())
    publish(entry, { items: next, status: "ready" })
  })
  queues.set(name, run.catch(() => undefined))
  return run
}

/**
 * Persistent list of records in IndexedDB, shared by every component that uses
 * the same `name`. `seed` is written only when nothing is stored under `name`.
 * Writes reject with the storage error and leave the last good items in place.
 */
export function useCollection<T extends { id: string }>(
  name: string,
  seed?: T[]
): Collection<T> {
  const entry = getEntry(name, seed)
  const snapshot = useSyncExternalStore(
    (listener) => {
      entry.listeners.add(listener)
      return () => entry.listeners.delete(listener)
    },
    () => entry.snapshot
  ) as Snapshot<T>

  const actions = useMemo(
    () => ({
      add: (item: T) => mutate<T>(name, entry, (items) => [...items, item]),
      update: (id: string, patch: Partial<T>) =>
        mutate<T>(name, entry, (items) =>
          items.some((item) => item.id === id)
            ? items.map((item) => (item.id === id ? { ...item, ...patch } : item))
            : null
        ),
      remove: (id: string) =>
        mutate<T>(name, entry, (items) =>
          items.some((item) => item.id === id)
            ? items.filter((item) => item.id !== id)
            : null
        ),
      replaceAll: (items: T[]) => mutate<T>(name, entry, () => items),
    }),
    [name, entry]
  )

  return { ...snapshot, ...actions }
}

/** Serializes every stored collection as `{"version":1,"collections":{...}}`. */
export async function exportAll(): Promise<string> {
  await Promise.all([...queues.values()])
  await Promise.all([...entriesByName.values()].map((entry) => entry.loaded))
  const collections: Record<string, unknown> = {}
  for (const [key, value] of await entries(db())) collections[String(key)] = value
  return JSON.stringify({ version: 1, collections })
}

/**
 * Replaces the named collections with the imported ones and leaves others
 * untouched. Rejects without writing anything when the JSON is invalid, the
 * version is not 1, or any collection is not an array.
 */
export async function importAll(json: string): Promise<void> {
  const parsed: unknown = JSON.parse(json)
  if (typeof parsed !== "object" || parsed === null) {
    throw new Error("Import is not a JSON object")
  }
  const { version, collections } = parsed as Record<string, unknown>
  if (version !== 1) throw new Error(`Unsupported export version: ${String(version)}`)
  if (typeof collections !== "object" || collections === null || Array.isArray(collections)) {
    throw new Error("Import has no collections object")
  }
  const incoming = Object.entries(collections)
  for (const [name, items] of incoming) {
    if (!Array.isArray(items)) throw new Error(`Collection "${name}" is not an array`)
  }

  // reserve every affected queue before the first await so mutations called after this point wait for the import
  const settled = incoming.map(([name]) => queueTail(name))
  const opened = incoming.flatMap(([name]) => entriesByName.get(name) ?? [])
  const run = Promise.all(settled).then(async () => {
    await Promise.all(opened.map((entry) => entry.loaded))
    await setMany(incoming, db())
    for (const [name, items] of incoming) {
      const entry = entriesByName.get(name)
      if (entry) publish(entry, { items: items as { id: string }[], status: "ready" })
    }
  })
  const tail = run.catch(() => undefined)
  for (const [name] of incoming) queues.set(name, tail)
  return run
}

import { useEffect, type ReactNode } from "react"

import { Toaster } from "@/components/ui/sonner"
import { TooltipProvider } from "@/components/ui/tooltip"

/**
 * Applies the OS light/dark preference to <html> when nothing else has set a
 * theme class. Any later write to the class list by a ThemeProvider or a manual
 * toggle, even to the value already applied, hands ownership to that writer for good.
 */
function useSystemTheme() {
  useEffect(() => {
    const root = document.documentElement
    if (root.classList.contains("light") || root.classList.contains("dark")) return

    const query = window.matchMedia("(prefers-color-scheme: dark)")
    const observer = new MutationObserver(() => release())
    let owned = true

    function release() {
      owned = false
      observer.disconnect()
      query.removeEventListener("change", sync)
    }

    function sync() {
      if (observer.takeRecords().length > 0) return release()
      root.classList.remove("light", "dark")
      root.classList.add(query.matches ? "dark" : "light")
      observer.takeRecords()
    }

    sync()
    observer.observe(root, { attributes: true, attributeFilter: ["class"] })
    query.addEventListener("change", sync)

    return () => {
      if (owned && observer.takeRecords().length === 0) root.classList.remove("light", "dark")
      release()
    }
  }, [])
}

/**
 * Page frame for a mini app: title bar with an optional toolbar, an optional
 * sidebar, and a scrolling main area. Provides the tooltip and toast hosts
 * that blocks rely on.
 */
export function AppShell({
  title,
  sidebar,
  toolbar,
  children,
}: {
  title: string
  sidebar?: ReactNode
  toolbar?: ReactNode
  children: ReactNode
}) {
  useSystemTheme()

  return (
    <TooltipProvider>
      <div className="flex h-svh flex-col bg-background text-foreground">
        <header data-mini="shell-header" className="flex h-10 shrink-0 items-center gap-3 border-b px-3">
          <h1 data-mini="title" className="text-sm font-semibold tracking-tight">{title}</h1>
          <div className="ml-auto flex items-center gap-1">{toolbar}</div>
        </header>
        <div className="flex min-h-0 flex-1">
          {sidebar ? (
            <aside data-mini="shell-sidebar" className="w-56 shrink-0 overflow-y-auto border-r bg-sidebar p-2 text-sidebar-foreground">
              {sidebar}
            </aside>
          ) : null}
          <main data-mini="shell-main" className="min-w-0 flex-1 overflow-auto">{children}</main>
        </div>
      </div>
      <Toaster />
    </TooltipProvider>
  )
}

import type { ReactNode } from "react"
import { AlertCircleIcon, InboxIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"

/** Centered placeholder for a view with nothing to show; `action` is typically a Button. */
export function EmptyState({
  title,
  description,
  action,
}: {
  title: string
  description?: string
  action?: ReactNode
}) {
  return (
    <div className="flex h-full min-h-40 flex-col items-center justify-center gap-2 p-6 text-center">
      <InboxIcon className="size-5 text-muted-foreground" aria-hidden />
      <p className="text-sm font-medium">{title}</p>
      {description ? (
        <p className="max-w-sm text-xs text-muted-foreground">{description}</p>
      ) : null}
      {action ? <div className="mt-1">{action}</div> : null}
    </div>
  )
}

/** Skeleton rows announced to assistive tech as a polite status. */
export function LoadingState({ label = "Loading" }: { label?: string }) {
  return (
    <div role="status" aria-live="polite" className="flex flex-col gap-2 p-4">
      <span className="sr-only">{label}</span>
      <Skeleton className="h-4 w-1/3" />
      <Skeleton className="h-4 w-full" />
      <Skeleton className="h-4 w-5/6" />
      <Skeleton className="h-4 w-2/3" />
    </div>
  )
}

/** Shows the error message and a Retry button when `onRetry` is given. */
export function ErrorState({
  error,
  onRetry,
}: {
  error: Error
  onRetry?: () => void
}) {
  return (
    <div
      role="alert"
      className="flex h-full min-h-40 flex-col items-center justify-center gap-2 p-6 text-center"
    >
      <AlertCircleIcon className="size-5 text-destructive" aria-hidden />
      <p className="text-sm font-medium">Something went wrong</p>
      <p className="max-w-sm text-xs break-words text-muted-foreground">
        {error.message}
      </p>
      {onRetry ? (
        <Button variant="outline" size="sm" className="mt-1" onClick={onRetry}>
          Retry
        </Button>
      ) : null}
    </div>
  )
}
